  // texts pass through byte-identical and are never mutated.
  it('alignCompareRows pads the shorter run with em-dash rows and never mutates entry texts', () => {
    const nine = run(1, ['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'f7', 'f8', 'f9']);
    const six = run(2, ['g1', 'g2', 'g3', 'g4', 'g5', 'g6']);
    const before = JSON.stringify([nine.entries, six.entries]);
    const rows = alignCompareRows(nine, six);
    expect(rows).toHaveLength(9);
    expect(rows.map((r) => r.n)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    expect(rows[0]).toEqual({ n: 1, left: 'f1', right: 'g1' });
    expect(rows[6].right).toBe('—');
    expect(rows[7].right).toBe('—');
    expect(rows[8].right).toBe('—');
    expect(rows[8].left).toBe('f9');
    expect(JSON.stringify([nine.entries, six.entries])).toBe(before);
  });

