    expect(alignCompareRows(run(1, ['a', 'b']), run(2, ['c', 'd']))).toEqual([
      { n: 1, left: 'a', right: 'c' },
      { n: 2, left: 'b', right: 'd' },
    ]);
  });

  // PINS: the two-distinct-runs branch — first push fills A, second fills
  // B, a third distinct run shifts A <- old B, B <- new.
  it('nextCompareSlots fills A then B, then shifts A <- old B, B <- new', () => {
    let slots = { a: null, b: null };
    let next = nextCompareSlots(slots, run(1, ['f1', 'f2']));
    expect([next.a?.run, next.b?.run, next.changed]).toEqual([1, null, true]);
